-- ManakMitra Phase 18 — official BIS knowledge expansion (additive, idempotent)
-- This migration adds curated/paraphrased public BIS knowledge only. It does not claim to contain the full BIS standards corpus.

create table if not exists public.knowledge_documents (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  content text not null,
  category text,
  source text not null,
  source_url text not null,
  source_updated_at date,
  knowledge_status text not null default 'official_verified' check (knowledge_status in ('official_verified','demonstration_mock','application_generated')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists idx_knowledge_documents_category on public.knowledge_documents(category);
create index if not exists idx_knowledge_documents_fts on public.knowledge_documents using gin(to_tsvector('english', coalesce(title,'') || ' ' || coalesce(content,'')));
alter table public.knowledge_documents enable row level security;


