insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('product_certification_process','Product Certification Process — Scheme I and Scheme IV','BIS product certification is operated under conformity assessment schemes. The BIS product certification process page identifies Scheme-I as the product certification scheme for use of the Standard Mark and Scheme-IV as the certificate of conformity route. BIS publishes guidelines covering grant of licence, non-conformity, unsatisfactory performance, scope changes, renewal, retesting, factory surveillance and market surveillance. Product-specific guidance can include sampling guidance, testing equipment, Scheme of Inspection and Testing (SIT), grouping guidance and scope information. Applications for product certification are handled online through the BIS application portal.','product','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-process/?lang=en','2026-02-25') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('product_certification_faq','Product Certification FAQ — core rules','BIS states that a licence permits use of a specified Standard Mark for goods or articles conforming to the relevant standard. Manufacturers can identify an applicable Indian Standard using BIS search facilities. Products can be made subject to compulsory certification through government notification and Quality Control Orders. BIS describes manufacturer requirements as including suitable manufacturing infrastructure, process controls, quality-control and testing capability, with conformity to the relevant Indian Standard. Product certification applications are submitted online. Product manuals may contain sampling, testing-equipment, SIT, grouping and scope information. BIS also describes separate applications for different products/Indian Standards and different factory locations.','product','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-faq/?lang=en','2026-02-25') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('compulsory_certification','Products under Compulsory Certification and QCOs','BIS explains that certification is generally voluntary, but the Central Government can make compliance compulsory for specified products. The BIS compulsory-certification page groups such products under Scheme-I, Scheme-II, Scheme-IV and Scheme-X and provides access to Quality Control Order information and upcoming QCO implementation information. A QCO can require use of a BIS Standard Mark or other conformity route for covered products from its effective date.','compulsory','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/products-under-compulsory-certification/?lang=en','2026-04-15') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('know_your_standard','Know Your Standard','BIS describes Know Your Standard as a one-stop feature for information related to a selected Indian Standard. Search can be performed by IS number or keyword/product name. BIS says the feature can expose basic standard documents, amendments, gazette notifications, Scheme of Testing and Inspection information, licence lists, laboratories associated with the standard, classification information and committee information.','know','Bureau of Indian Standards','https://www.bis.gov.in/know-your-standard/?lang=en','2026-05-08') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('laboratory_services','BIS Laboratory Services and Recognition','BIS states that testing facilities used for conformity assessment can include BIS laboratories, BIS-recognised laboratories under the Laboratory Recognition Scheme and certain government test facilities that have been empanelled. BIS maintains a laboratory information system where users can search laboratory information, including by Indian Standard. The laboratory FAQ directs applicants to the LIMS portal for standard-wise laboratory and test-facility information.','laboratory','Bureau of Indian Standards','https://www.bis.gov.in/laboratorys/laboratory-services-overview/laboratory-faq/?lang=en','2026-02-12') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('hallmarking_general','Hallmarking — general information','BIS describes hallmarking as the determination and official recording of the proportionate content of precious metal in precious-metal articles. BIS states that gold and silver are currently within the Indian hallmarking framework. BIS identifies standards including IS 1417 for gold jewellery/artefacts, IS 2112 for silver jewellery/artefacts and IS 15820 for assaying and hallmarking centres. BIS also explains that HUID is a unique identification number used as a component of hallmarking for covered gold jewellery and can be verified using BIS Care.','hallmarking','Bureau of Indian Standards','https://www.bis.gov.in/hallmarking-overview/hallmarking-faqs/hallmarking-faq/?lang=en','2025-11-26') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('hallmarking_mandatory','Mandatory Hallmarking Orders','BIS maintains the mandatory hallmarking order page and publishes the original order plus subsequent amendments and phase-wise coverage information. The page records amendments through August 2026, showing that hallmarking requirements can change over time. For current applicability, ManakMitra should therefore prefer source-backed current BIS order data over older summaries.','hallmarking','Bureau of Indian Standards','https://www.bis.gov.in/hallmarking-overview/mandatory-hallmarking-order/?lang=en','2026-09-01') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('consumer_faq','BIS Consumer Engagement FAQ','BIS describes consumer engagement as including awareness, consumer protection and complaint-related activities. BIS identifies Standard Marks including the ISI Mark and Eco Mark for relevant Scheme-I products, the Registration Mark for Scheme-II products and the Hallmark for hallmarked articles. BIS also provides complaint channels for issues such as quality of BIS-certified products, misuse of the Standard Mark and violation of Quality Control Orders.','consumer','Bureau of Indian Standards','https://www.bis.gov.in/consumer-overview/for-consumers-faq/?lang=en','2026-02-12') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('system_certification','BIS Management Systems Certification','BIS operates management-system certification schemes. Its overview lists areas including quality management, environmental management, food-safety management, energy management, occupational health and safety, service quality, HACCP, medical-device quality management and other schemes. BIS states that organizations can apply online, and the certification process can involve Stage 1 and Stage 2 audits. BIS also describes surveillance after certification and renewal procedures.','system','Bureau of Indian Standards','https://www.bis.gov.in/system-certification-overview/?lang=en','2026-05-20') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('system_certification_faq','Management Systems Certification FAQ','BIS defines management-system certification as third-party certification demonstrating an organization''s capability to meet the requirements of a management-system standard. The FAQ lists multiple certification schemes, explains integrated management-system certification, and describes online application followed by Stage 1 and Stage 2 audits when applicable. The FAQ also states that management-system certification is available to different types of organizations that want to demonstrate consistent ability to meet customer and regulatory requirements.','system','Bureau of Indian Standards','https://www.bis.gov.in/system-certification-overview/system-certification-faq/?lang=en','2026-05-20') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('fmcs','Foreign Manufacturers Certification Scheme (FMCS)','BIS describes FMCS as a certification route for foreign manufacturers seeking BIS licences for products other than electronic and information-technology products covered by the separate registration scheme. BIS notes that certification is generally voluntary unless a product is brought under a compulsory requirement such as a Quality Control Order. The applicable current product list and requirements should be checked against BIS sources.','fmcs','Bureau of Indian Standards','https://www.bis.gov.in/fmcs/fmcs-faqs/?lang=en','2026-02-12') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('training','BIS National Institute of Training for Standardization FAQ','BIS training information states that NITS is located in Sector 62, Noida. Training programmes are generally conducted Monday to Friday during normal working hours, with some programmes potentially extending to weekends. Applicants can register online, and direct applications are accepted for many on-campus programmes. BIS also describes the possibility of customized programmes where the topic is within BIS''s domain.','training','Bureau of Indian Standards','https://www.services.bis.gov.in/php/BIS_2.0/trainings/HomeUser/Faq/','2026-09-20') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('standards_catalogue_context','Indian Standards catalogue context','BIS''s public standards services expose standard-level metadata such as IS number, title, technical department, language, classification and cross-references. BIS standard detail pages can also show referenced Indian Standards and international standards. These catalogue records should be treated as metadata about the standard; the full normative text of an Indian Standard should not be invented from catalogue metadata.','standards','Bureau of Indian Standards','https://www.services.bis.gov.in/php/BIS_2.0/bisconnect/standard_review/Standard_review/Isdetails','2026-09-20') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('application_license','Apply for BIS Product Certification Licence','BIS''s application guidance starts with identifying the Indian Standard applicable to the product. Applicants are then expected to assess manufacturing infrastructure, process controls, quality control and testing capabilities against the relevant standard. BIS states that applications are accepted online and provides links to product-specific technical manuals and fee information.','application','Bureau of Indian Standards','https://www.bis.gov.in/apply-for-a-license/?lang=en','2026-02-03') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.knowledge_documents (slug,title,content,category,source,source_url,source_updated_at) values ('product_specific_guidelines','Product-specific manuals, SIT and grouping guidance','BIS publishes product-specific information including product manuals, Scheme of Inspection and Testing material, grouping guidance and implementation guidance for revisions or amendments. Product-specific manuals can contain requirements needed to understand a particular certification scope and testing process. These documents should be associated with the exact Indian Standard and version when indexed.','product','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-specific-information-2/?lang=en','2025-12-22') on conflict (slug) do update set title=excluded.title, content=excluded.content, category=excluded.category, source=excluded.source, source_url=excluded.source_url, source_updated_at=excluded.source_updated_at, updated_at=now();
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What is a BIS licence?','A BIS licence authorizes use of a specified BIS Standard Mark for goods or articles that conform to the relevant standard, subject to the applicable conformity-assessment requirements.','product-certification','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What is a BIS licence?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Is BIS certification compulsory for every product?','No. BIS states that certification is generally voluntary, but the Central Government can make certification or conformity requirements compulsory for specified products through applicable legal notifications and Quality Control Orders.','product-certification','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('Is BIS certification compulsory for every product?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'How can I find the Indian Standard for my product?','BIS provides standard-search facilities, including Know Your Standard, where an Indian Standard can be searched using an IS number or a keyword such as a product name.','standards','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/know-your-standard/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('How can I find the Indian Standard for my product?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Where can I find product manuals?','BIS publishes product-specific manuals and related guidance under Product Certification → Product Specific Information. These materials can include sampling, testing equipment, SIT, grouping and scope information.','product-certification','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('Where can I find product manuals?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Can one application cover multiple products and Indian Standards?','BIS product-certification FAQ states that a separate application is required for each product and Indian Standard, even when products are made at the same factory location.','product-certification','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('Can one application cover multiple products and Indian Standards?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Can the same application cover the same product made at different factories?','BIS states that a separate application is required for the same product when it is manufactured at different factory locations.','product-certification','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('Can the same application cover the same product made at different factories?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What testing laboratories can be used for BIS conformity assessment?','BIS identifies its own laboratories, BIS-recognised laboratories and certain empanelled government laboratories as testing facilities used for conformity assessment. Standard-wise laboratory information is available through the BIS LIMS portal.','laboratory','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/laboratorys/laboratory-services-overview/laboratory-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What testing laboratories can be used for BIS conformity assessment?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'How do I search BIS laboratory facilities by standard?','BIS directs users to the Laboratory Information Management System and specifically identifies a search-by-IS-number route for standard-wise laboratory information.','laboratory','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/laboratorys/laboratory-services-overview/laboratory-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('How do I search BIS laboratory facilities by standard?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What is hallmarking?','BIS defines hallmarking as the accurate determination and official recording of the proportionate content of precious metal in precious-metal articles.','hallmarking','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/hallmarking-overview/hallmarking-faqs/hallmarking-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What is hallmarking?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Which precious metals are currently covered by hallmarking in India?','BIS states that gold and silver are currently within the hallmarking framework.','hallmarking','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/hallmarking-overview/hallmarking-faqs/hallmarking-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('Which precious metals are currently covered by hallmarking in India?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What is HUID?','HUID is the Hallmark Unique Identification number used as a component of hallmarking for covered gold jewellery. BIS describes it as a unique six-digit alphanumeric identifier and provides a BIS Care verification feature.','hallmarking','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/hallmarking-overview/hallmarking-faqs/hallmarking-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What is HUID?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What marks can BIS use for conformity schemes?','BIS consumer guidance identifies the ISI Mark and Eco Mark for relevant Scheme-I products, the Registration Mark for Scheme-II products and the Hallmark for hallmarked articles.','consumer','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/consumer-overview/for-consumers-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What marks can BIS use for conformity schemes?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'How can I complain about a BIS-certified product?','BIS provides complaint channels for issues including quality of BIS-certified products, misuse of the BIS Standard Mark and violation of Quality Control Orders. BIS identifies online complaint routes including its consumer-facing systems and BIS Care.','consumer','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/consumer-overview/for-consumers-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('How can I complain about a BIS-certified product?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What is FMCS?','FMCS is the BIS certification scheme for foreign manufacturers seeking BIS licences for products other than electronic and IT products handled under the separate registration route.','fmcs','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/fmcs/fmcs-faqs/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What is FMCS?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Is BIS certification mandatory for imported products?','BIS states that certification is generally voluntary, but products covered by applicable compulsory requirements such as Quality Control Orders may require the relevant BIS conformity route before import or sale.','fmcs','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/fmcs/fmcs-faqs/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('Is BIS certification mandatory for imported products?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What is management-system certification?','BIS describes management-system certification as third-party certification demonstrating an organization’s capability to meet the requirements of a management-system standard.','systems','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/system-certification-overview/system-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What is management-system certification?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What management-system certifications does BIS offer?','BIS lists schemes including quality, environmental, food-safety, energy, occupational health and safety, service quality, HACCP, medical-device and other management-system certifications. The exact list should be checked against the current BIS page.','systems','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/system-certification-overview/system-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What management-system certifications does BIS offer?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What is integrated management-system certification?','BIS describes IMS as combining two or more management-system certifications so that documentation and audit activities can be integrated where appropriate.','systems','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/system-certification-overview/system-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What is integrated management-system certification?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'How does BIS management-system certification generally proceed?','BIS describes online application followed, where applicable, by Stage 1 and Stage 2 audits. Certification is granted when the relevant audit and certification requirements are satisfied.','systems','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/system-certification-overview/system-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('How does BIS management-system certification generally proceed?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Where is NITS located?','BIS training information lists the National Institute of Training for Standardization at A-20 & 21, Institutional Area, Sector 62, Noida, Uttar Pradesh.','training','official_verified','Bureau of Indian Standards','https://www.services.bis.gov.in/php/BIS_2.0/trainings/HomeUser/Faq/' where not exists (select 1 from public.faqs where lower(question)=lower('Where is NITS located?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Can an individual apply for BIS training?','BIS training FAQ states that direct applications from individuals are accepted for most on-campus programmes, while some specialised programmes use nomination routes.','training','official_verified','Bureau of Indian Standards','https://www.services.bis.gov.in/php/BIS_2.0/trainings/HomeUser/Faq/' where not exists (select 1 from public.faqs where lower(question)=lower('Can an individual apply for BIS training?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Can BIS arrange customized training?','BIS training information says customized training can be arranged when the requested topic falls within BIS’s domain of work.','training','official_verified','Bureau of Indian Standards','https://www.services.bis.gov.in/php/BIS_2.0/trainings/HomeUser/Faq/' where not exists (select 1 from public.faqs where lower(question)=lower('Can BIS arrange customized training?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Can I search a standard by product name?','Yes. BIS describes Know Your Standard as supporting searches by Indian Standard number or keyword such as a product name.','standards','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/know-your-standard/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('Can I search a standard by product name?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Does Know Your Standard contain only the standard PDF?','No. BIS describes the feature as providing access to a range of standard-related documents and data, including amendments, gazette notifications, SIT information, licence information, laboratory information and committee details where available.','standards','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/know-your-standard/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('Does Know Your Standard contain only the standard PDF?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What is a Quality Control Order?','A Quality Control Order is a government notification used to make specified product compliance requirements compulsory. BIS explains that covered products can be required to bear the applicable Standard Mark or follow the specified conformity route from the effective date.','product-certification','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What is a Quality Control Order?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What does a BIS product manual contain?','BIS explains that product manuals can include sampling guidance, test-equipment lists, Scheme of Inspection and Testing, grouping guidance and the scope of certification.','product-certification','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What does a BIS product manual contain?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'How are BIS licences granted for products?','BIS describes assessment of manufacturing infrastructure, process controls, quality-control and testing capability, together with establishment of product conformity through applicable testing and assessment arrangements.','product-certification','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/product-certification/product-certification-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('How are BIS licences granted for products?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'Can BIS use third-party laboratories?','Yes. BIS states that conformity assessment can use BIS laboratories, BIS-recognised laboratories and certain empanelled government laboratories, subject to the applicable scheme and requirements.','laboratory','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/laboratorys/laboratory-services-overview/laboratory-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('Can BIS use third-party laboratories?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'How often can hallmarking requirements change?','BIS maintains a mandatory hallmarking order page with amendments and phase-wise coverage updates. Current applicability should therefore be checked against the latest BIS order and amendments rather than relying on an old summary.','hallmarking','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/hallmarking-overview/hallmarking-faqs/hallmarking-faq/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('How often can hallmarking requirements change?'));
insert into public.faqs (question,answer,category,knowledge_status,source,source_url) select 'What is the difference between a standard and a certification licence?','An Indian Standard is the technical standard or specification. A certification licence is an authorization to use the applicable BIS Standard Mark under a conformity-assessment scheme when the relevant requirements have been met.','standards','official_verified','Bureau of Indian Standards','https://www.bis.gov.in/know-your-standard/?lang=en' where not exists (select 1 from public.faqs where lower(question)=lower('What is the difference between a standard and a certification licence?'));
insert into public.standards (is_number,title,description,category,dept,status,language,knowledge_status,source,source_url) select 'IS 875 (Part 1):1987','Code of practice for design loads (other than earthquake) for buildings and structures: Part 1 Dead loads — Unit weights of building materials and stored materials','Design loads for dead-load calculations in buildings and structures.','civil','CED 37','Active','English','official_verified','Bureau of Indian Standards public standard metadata','https://www.services.bis.gov.in/php/BIS_2.0/bisconnect/standard_review/Standard_review/Isdetails' where not exists (select 1 from public.standards where is_number='IS 875 (Part 1):1987');
